/**
 * Unit tests for js/enhanceSolutionDesignDescriptionAndAssess.js
 * (gh-1228 CRAP characterization).
 *
 * Pins parseSDCoreEnhancementResponse's file-reading contract (via action)
 * and the action() update/assign flow including every non-fatal path.
 */

function loadEnhanceSD(mocks) {
    var defaults = {
        file_read: function() { return null; },
        file_write: function() {}
    };
    var g = Object.assign({}, defaults, mocks || {});
    var outputFilesMock = g.__files || { readOutputFile: function(name) {
        return name === 'response.md' ? 'New description' : 'graph TD; A-->B;';
    } };
    return loadModule(
        'js/enhanceSolutionDesignDescriptionAndAssess.js',
        makeRequire({
            './common/jiraHelpers.js': { extractTicketKey: function() { return null; } },
            './config.js': configModule,
            './configLoader.js': g.__configLoader || { loadProjectConfig: function() { return {}; } },
            './common/outputFiles.js': outputFilesMock,
            './common/tokenUsageComment.js': g.__tokenUsage || { postTokenUsageComments: function() {} },
            './common/trackers.js': { createTracker: function(config, customParams) { return g.__tracker; } }
        }),
        g
    );
}

function sdTracker(overrides) {
    var calls = { updateDescription: [], updateField: [], assignForReview: [] };
    var t = {
        calls: calls,
        updateDescription: function(key, description) { calls.updateDescription.push({ key: key, description: description }); },
        updateField: function(key, field, value) { calls.updateField.push({ key: key, field: field, value: value }); },
        assignForReview: function(key, initiator, wipLabel, status) {
            calls.assignForReview.push({ key: key, initiator: initiator, wipLabel: wipLabel, status: status });
            return { success: true };
        }
    };
    for (var k in (overrides || {})) { t[k] = overrides[k]; }
    return t;
}

function enhanceParams(overrides) {
    return Object.assign({
        ticket: { key: 'PROJ-20' },
        initiator: 'acc',
        metadata: { contextId: 'enhance_sd' },
        jobParams: {}
    }, overrides || {});
}

suite('enhanceSolutionDesignDescriptionAndAssess — parse (via action)', function() {

    test('happy path — description and diagram read, ticket updated 2/2', function() {
        var tracker = sdTracker();
        var mod = loadEnhanceSD({ __tracker: tracker });

        var r = mod.action(enhanceParams());

        assert.equal(r.success, true, 'action succeeds');
        assert.contains(r.message, '2/2');
        assert.equal(r.enhancementData.description, 'New description', 'description trimmed/passed through');
        assert.equal(r.enhancementData.diagram, 'graph TD; A-->B;', 'diagram read from diagram.md');
        assert.equal(r.updateResults.descriptionUpdated, true, 'description updated');
        assert.equal(r.updateResults.diagramUpdated, true, 'diagram updated');
        assert.deepEqual(tracker.calls.updateDescription, [{ key: 'PROJ-20', description: 'New description' }], 'description pushed to tracker');
        assert.equal(tracker.calls.updateField.length, 1, 'diagrams field updated once');
        assert.contains(tracker.calls.updateField[0].value, 'graph TD; A-->B;', 'diagram wrapped for the diagrams field');
        assert.deepEqual(
            [tracker.calls.assignForReview[0].key, tracker.calls.assignForReview[0].initiator,
             tracker.calls.assignForReview[0].wipLabel, tracker.calls.assignForReview[0].status],
            ['PROJ-20', 'acc', 'enhance_sd_wip', configModule.STATUSES.READY_FOR_DEVELOPMENT],
            'assign-for-review flow ran with the context WIP label'
        );
    });

    test('missing description file fails the action before any tracker call', function() {
        var tracker = sdTracker();
        var mod = loadEnhanceSD({
            __tracker: tracker,
            __files: { readOutputFile: function(name) {
                return name === 'response.md' ? '' : 'graph TD; A-->B;';
            } }
        });

        var r = mod.action(enhanceParams());

        assert.equal(r.success, false, 'fails without a description');
        assert.equal(r.error, 'Failed to read enhancement data from output files', 'error message pinned');
        assert.equal(tracker.calls.updateDescription.length, 0, 'no tracker writes');
        assert.equal(tracker.calls.assignForReview.length, 0, 'no assignment');
    });

    test('description read failure (throw) fails the action', function() {
        var tracker = sdTracker();
        var mod = loadEnhanceSD({
            __tracker: tracker,
            __files: { readOutputFile: function(name) {
                if (name === 'response.md') { throw new Error('disk error'); }
                return 'graph TD; A-->B;';
            } }
        });

        var r = mod.action(enhanceParams());

        assert.equal(r.success, false, 'fails on read error');
        assert.equal(r.error, 'Failed to read enhancement data from output files', 'same contract error');
        assert.equal(tracker.calls.updateDescription.length, 0, 'no tracker writes');
    });

    test('whitespace-only description is rejected', function() {
        var tracker = sdTracker();
        var mod = loadEnhanceSD({
            __tracker: tracker,
            __files: { readOutputFile: function(name) {
                return name === 'response.md' ? '   \n\t  ' : 'graph TD; A-->B;';
            } }
        });

        var r = mod.action(enhanceParams());

        assert.equal(r.success, false, 'blank description fails');
        assert.equal(r.error, 'Failed to read enhancement data from output files', 'contract error');
        assert.equal(tracker.calls.updateDescription.length, 0, 'no tracker writes');
    });

    test('missing diagram file falls back to the default CORE_GRAPH diagram', function() {
        var tracker = sdTracker();
        var mod = loadEnhanceSD({
            __tracker: tracker,
            __files: { readOutputFile: function(name) {
                return name === 'response.md' ? 'New description' : '';
            } }
        });

        var r = mod.action(enhanceParams());

        assert.equal(r.success, true, 'still succeeds');
        assert.contains(r.message, '2/2');
        assert.equal(r.enhancementData.diagram, configModule.DIAGRAM_DEFAULTS.CORE_GRAPH, 'default diagram used');
        assert.contains(tracker.calls.updateField[0].value, configModule.DIAGRAM_DEFAULTS.CORE_GRAPH, 'default diagram pushed');
    });

    test('diagram read failure falls back to the default CORE_GRAPH diagram', function() {
        var tracker = sdTracker();
        var mod = loadEnhanceSD({
            __tracker: tracker,
            __files: { readOutputFile: function(name) {
                if (name === 'diagram.md') { throw new Error('disk error'); }
                return 'New description';
            } }
        });

        var r = mod.action(enhanceParams());

        assert.equal(r.success, true, 'still succeeds');
        assert.equal(r.enhancementData.diagram, configModule.DIAGRAM_DEFAULTS.CORE_GRAPH, 'default diagram used');
    });

    test('whitespace-only diagram falls back to the default CORE_GRAPH diagram', function() {
        var tracker = sdTracker();
        var mod = loadEnhanceSD({
            __tracker: tracker,
            __files: { readOutputFile: function(name) {
                return name === 'response.md' ? 'New description' : '   ';
            } }
        });

        var r = mod.action(enhanceParams());

        assert.equal(r.success, true, 'still succeeds');
        assert.equal(r.enhancementData.diagram, configModule.DIAGRAM_DEFAULTS.CORE_GRAPH, 'trimmed-empty diagram replaced by default');
    });
});

suite('enhanceSolutionDesignDescriptionAndAssess — action flow', function() {

    test('failed assignment short-circuits with the assign result', function() {
        var tracker = sdTracker({
            assignForReview: function() { return { success: false, error: 'assignee unknown' }; }
        });
        var mod = loadEnhanceSD({ __tracker: tracker });

        var r = mod.action(enhanceParams());

        assert.deepEqual(r, { success: false, error: 'assignee unknown' }, 'assign failure returned as-is');
        assert.equal(tracker.calls.updateDescription.length, 1, 'description was already updated before the assign');
    });

    test('tracker update failures are collected — action still succeeds with 0/2', function() {
        var tracker = sdTracker({
            updateDescription: function() { throw new Error('desc update failed'); },
            updateField: function() { throw new Error('field update failed'); }
        });
        var mod = loadEnhanceSD({ __tracker: tracker });

        var r = mod.action(enhanceParams());

        assert.equal(r.success, true, 'update failures are non-fatal');
        assert.contains(r.message, '0/2');
        assert.equal(r.updateResults.descriptionUpdated, false, 'description not updated');
        assert.equal(r.updateResults.diagramUpdated, false, 'diagram not updated');
        assert.equal(r.updateResults.errors.length, 2, 'both errors recorded');
        assert.contains(r.updateResults.errors[0], 'desc update failed');
        assert.contains(r.updateResults.errors[1], 'field update failed');
    });

    test('token usage comment failure is non-fatal', function() {
        var tracker = sdTracker();
        var mod = loadEnhanceSD({
            __tracker: tracker,
            __tokenUsage: { postTokenUsageComments: function() { throw new Error('usage failed'); } }
        });

        var r = mod.action(enhanceParams());

        assert.equal(r.success, true, 'still succeeds');
        assert.contains(r.message, '2/2');
    });

    test('partial update success reports 1/2', function() {
        var tracker = sdTracker({
            updateField: function() { throw new Error('field update failed'); }
        });
        var mod = loadEnhanceSD({ __tracker: tracker });

        var r = mod.action(enhanceParams());

        assert.equal(r.success, true, 'still succeeds');
        assert.contains(r.message, '1/2');
        assert.equal(r.updateResults.descriptionUpdated, true, 'description updated');
        assert.equal(r.updateResults.diagramUpdated, false, 'diagram not updated');
    });

    test('tracker creation failure is reported as a failure result (outer catch)', function() {
        var mod = loadEnhanceSD({
            __tracker: sdTracker(),
            __configLoader: { loadProjectConfig: function() { throw new Error('no config'); } }
        });

        var r = mod.action(enhanceParams());

        assert.equal(r.success, false, 'fails');
        assert.contains(r.error, 'no config');
    });

    test('missing ticket key is reported as a failure result (outer catch)', function() {
        var tracker = sdTracker();
        var mod = loadEnhanceSD({ __tracker: tracker });

        var r = mod.action({ jobParams: {} });

        assert.equal(r.success, false, 'fails without a ticket key');
        assert.ok(r.error.indexOf('TypeError') !== -1 || r.error.indexOf('key') !== -1, 'underlying error surfaced');
        assert.equal(tracker.calls.updateDescription.length, 0, 'no tracker writes');
    });
});

/**
 * Unit tests for js/prepareBugFixBatchContext.js (gh-1228 CRAP characterization).
 *
 * Pins the pre-CLI action(): batch bug discovery, per-bug context fetch,
 * batch_bugs.md rendering, In Development transition, and every non-fatal
 * failure path.
 */

function loadBugFixBatchContext(mocks) {
    var defaults = {
        cli_execute_command: function() { return ''; },
        file_write: function() {},
        file_read: function() { return null; }
    };
    var g = Object.assign({}, defaults, mocks || {});
    var tracker = g.__tracker;
    return loadModule(
        'js/prepareBugFixBatchContext.js',
        makeRequire({
            './configLoader.js': g.__configLoader || { loadProjectConfig: function() {
                return { jira: { statuses: { IN_DEVELOPMENT: 'In Development' } } };
            } },
            './common/pullRequest.js': { cleanCommandOutput: function(output) { return output; } },
            './fetchQuestionsToInput.js': g.__fetchQuestions || { action: function() {} },
            './fetchLinkedTestsToInput.js': g.__fetchTests || { action: function() {} },
            './config.js': configModule,
            './common/trackers.js': { createTracker: function(config, customParams) { return tracker; } }
        }),
        g
    );
}

function batchTracker(overrides) {
    var calls = { searchIssues: [], getIssue: [], moveToStatus: [] };
    var t = {
        calls: calls,
        searchIssues: function(jql, opts) {
            calls.searchIssues.push({ jql: jql, opts: opts });
            return [
                { key: 'PROJ-2', fields: { summary: 'Bug two', status: { name: 'To Do' }, issuetype: { name: 'Bug' } } },
                { key: 'PROJ-3', fields: { summary: 'Bug three', status: { name: 'In Progress' }, issuetype: { name: 'Bug' } } },
                { key: 'PROJ-4', fields: { summary: 'Not a bug', issuetype: { name: 'Story' } } }
            ];
        },
        getIssue: function(key, fields) {
            calls.getIssue.push({ key: key, fields: fields });
            return { key: key, fields: { summary: 'Epic summary', description: 'Epic description', status: { name: 'To Do' } } };
        },
        moveToStatus: function(key, status) { calls.moveToStatus.push({ key: key, status: status }); }
    };
    for (var k in (overrides || {})) { t[k] = overrides[k]; }
    return t;
}

function batchParams(overrides) {
    return Object.assign({
        inputFolderPath: 'input/PROJ-1',
        ticket: { key: 'PROJ-1', fields: { summary: 'Batch epic' } },
        jobParams: {}
    }, overrides || {});
}

suite('prepareBugFixBatchContext — action', function() {

    test('happy path — filters to Bug issues, fetches per-bug context, writes batch_bugs.md, moves epic', function() {
        var writes = {};
        var cmds = [];
        var questions = [];
        var tests = [];
        var tracker = batchTracker();
        var mod = loadBugFixBatchContext({
            __tracker: tracker,
            cli_execute_command: function(args) { cmds.push(args); return ''; },
            file_write: function(p, c) { writes[p] = c; },
            __fetchQuestions: { action: function(p) { questions.push(p.ticket.key); } },
            __fetchTests: { action: function(p) { tests.push(p.ticket.key); } }
        });

        mod.action(batchParams());

        assert.equal(tracker.calls.searchIssues.length, 1, 'one JQL search');
        assert.contains(tracker.calls.searchIssues[0].jql, configModule.LABELS.BUG_FIX_BATCH, 'JQL filters by the batch label');
        assert.contains(tracker.calls.searchIssues[0].jql, 'PROJ-1', 'JQL scoped to the epic');
        assert.deepEqual(questions.sort(), ['PROJ-2', 'PROJ-3'], 'questions fetched for Bug issues only');
        assert.deepEqual(tests.sort(), ['PROJ-2', 'PROJ-3'], 'linked tests fetched for Bug issues only');
        var md = writes['input/PROJ-1/batch_bugs.md'];
        assert.ok(md, 'batch_bugs.md written into the epic input folder');
        assert.contains(md, 'PROJ-2', 'bug listed');
        assert.contains(md, 'PROJ-3', 'bug listed');
        assert.notContains(md, 'PROJ-4', 'non-Bug issue not listed');
        assert.contains(md, '# Bug-fix Batch — PROJ-1', 'epic header');
        assert.deepEqual(tracker.calls.moveToStatus, [{ key: 'PROJ-1', status: 'In Development' }], 'epic moved to In Development');
        assert.equal(cmds.length, 2, 'one mkdir per bug input folder');
    });

    test('epic without fields is fetched from the tracker', function() {
        var tracker = batchTracker();
        var mod = loadBugFixBatchContext({ __tracker: tracker, file_write: function() {} });

        mod.action(batchParams({ ticket: { key: 'PROJ-1' } }));

        assert.deepEqual(tracker.calls.getIssue, [{ key: 'PROJ-1', fields: ['summary', 'description', 'status', 'labels'] }], 'epic fetched with the field list');
    });

    test('epic fetch failure falls back to a key-only epic and still writes the batch file', function() {
        var writes = {};
        var tracker = batchTracker({
            getIssue: function() { throw new Error('epic fetch down'); }
        });
        var mod = loadBugFixBatchContext({ __tracker: tracker, file_write: function(p, c) { writes[p] = c; } });

        mod.action(batchParams({ ticket: { key: 'PROJ-1' } }));

        var md = writes['input/PROJ-1/batch_bugs.md'];
        assert.ok(md, 'batch_bugs.md still written');
        assert.contains(md, '# Bug-fix Batch — PROJ-1', 'fallback epic key used');
        assert.notContains(md, 'Epic summary', 'fetched summary not present');
    });

    test('search failure yields an empty batch with the no-bugs placeholder and still moves the epic', function() {
        var writes = {};
        var fetched = [];
        var tracker = batchTracker({
            searchIssues: function() { throw new Error('jql down'); }
        });
        var mod = loadBugFixBatchContext({
            __tracker: tracker,
            file_write: function(p, c) { writes[p] = c; },
            __fetchQuestions: { action: function(p) { fetched.push(p.ticket.key); } }
        });

        mod.action(batchParams());

        assert.contains(writes['input/PROJ-1/batch_bugs.md'], '_No bug-fix batch bugs found for this Epic._', 'placeholder rendered');
        assert.equal(fetched.length, 0, 'no per-bug fetches');
        assert.deepEqual(tracker.calls.moveToStatus, [{ key: 'PROJ-1', status: 'In Development' }], 'epic still moved');
    });

    test('per-bug question fetch failure is non-fatal — linked tests still fetched', function() {
        var tests = [];
        var tracker = batchTracker();
        var mod = loadBugFixBatchContext({
            __tracker: tracker,
            file_write: function() {},
            __fetchQuestions: { action: function() { throw new Error('questions down'); } },
            __fetchTests: { action: function(p) { tests.push(p.ticket.key); } }
        });

        mod.action(batchParams());

        assert.deepEqual(tests.sort(), ['PROJ-2', 'PROJ-3'], 'linked tests still fetched for every bug');
        assert.deepEqual(tracker.calls.moveToStatus, [{ key: 'PROJ-1', status: 'In Development' }], 'epic still moved');
    });

    test('per-bug linked-tests fetch failure is non-fatal', function() {
        var questions = [];
        var tracker = batchTracker();
        var mod = loadBugFixBatchContext({
            __tracker: tracker,
            file_write: function() {},
            __fetchQuestions: { action: function(p) { questions.push(p.ticket.key); } },
            __fetchTests: { action: function() { throw new Error('tests down'); } }
        });

        mod.action(batchParams());

        assert.deepEqual(questions.sort(), ['PROJ-2', 'PROJ-3'], 'questions still fetched for every bug');
        assert.equal(tracker.calls.moveToStatus.length, 1, 'epic still moved');
    });

    test('mkdir failure is non-fatal', function() {
        var tracker = batchTracker();
        var mod = loadBugFixBatchContext({
            __tracker: tracker,
            file_write: function() {},
            cli_execute_command: function() { throw new Error('mkdir failed'); }
        });

        mod.action(batchParams());

        assert.deepEqual(tracker.calls.moveToStatus, [{ key: 'PROJ-1', status: 'In Development' }], 'epic still moved');
    });

    test('moveToStatus failure is non-fatal', function() {
        var writes = {};
        var tracker = batchTracker({
            moveToStatus: function() { throw new Error('transition rejected'); }
        });
        var mod = loadBugFixBatchContext({ __tracker: tracker, file_write: function(p, c) { writes[p] = c; } });

        mod.action(batchParams());

        assert.ok(writes['input/PROJ-1/batch_bugs.md'], 'batch_bugs.md still written');
    });

    test('config load failure propagates (hard error)', function() {
        var mod = loadBugFixBatchContext({
            __tracker: batchTracker(),
            __configLoader: { loadProjectConfig: function() { throw new Error('bad config'); } }
        });

        assert.throws(function() { mod.action(batchParams()); }, 'action rethrows config failures');
    });

    test('workingDir from config is passed to every command', function() {
        var cmds = [];
        var tracker = batchTracker();
        var mod = loadBugFixBatchContext({
            __tracker: tracker,
            file_write: function() {},
            cli_execute_command: function(args) { cmds.push(args); return ''; },
            __configLoader: { loadProjectConfig: function() {
                return { workingDir: '/tmp/workspace', jira: { statuses: { IN_DEVELOPMENT: 'In Development' } } };
            } }
        });

        mod.action(batchParams());

        assert.equal(cmds.length, 2, 'one command per bug folder');
        assert.equal(cmds[0].workingDirectory, '/tmp/workspace', 'workingDirectory applied');
    });
});

suite('prepareBugFixBatchContext — findBugsInEpic and rendering', function() {

    test('findBugsInEpic with an explicit tracker skips tracker creation', function() {
        var tracker = batchTracker();
        var mod = loadBugFixBatchContext({ __tracker: tracker });
        var created = [];
        var originalCreate = tracker;
        // Sanity: direct call with explicit tracker
        var bugs = mod.findBugsInEpic('PROJ-1', originalCreate, { jira: {} });
        assert.equal(bugs.length, 2, 'only Bug issues kept');
        assert.equal(bugs[0].key, 'PROJ-2', 'first bug');
    });

    test('issuetype read failure filters the issue out instead of throwing', function() {
        var tracker = batchTracker({
            searchIssues: function() {
                return [
                    { key: 'PROJ-2', fields: { summary: 'Broken issuetype' } }, // fields.issuetype undefined
                    { key: 'PROJ-3', fields: { issuetype: { name: 'Bug' } } }
                ];
            }
        });
        var mod = loadBugFixBatchContext({ __tracker: tracker });
        var bugs = mod.findBugsInEpic('PROJ-1', tracker, {});
